#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // _fict_[i] = (DATA_TYPE) i;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / cast<int>(nx);
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<int>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // Simple but effective schedule for initialization:
    Target target = get_host_target();
    const int vec_width = natural_vector_size(type_of<num_t>(), target);

    // Vectorize the 1D initialization of fict.
    init_fict
        .compute_root()
        .vectorize(t, vec_width);

    // For 2D fields, make j (x/column) the vectorized inner loop
    // and parallelize over i (rows).
    init_ex
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_ey
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_hz
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // Expressions for domain extents, used for boundary handling.
    Expr ny_expr      = ex_param.dim(0).extent();  // number of columns (j dimension)
    Expr nx_expr      = ex_param.dim(1).extent();  // number of rows (i dimension)
    Expr ny_minus_one = ny_expr - 1;
    Expr nx_minus_one = nx_expr - 1;

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // ------------------------------------------------------------------
    // Pure, branch-based definitions that exactly match the original C
    // loop semantics but avoid out-of-bounds accesses by clamping
    // neighbor indices. The clamping only affects values that are
    // discarded by a select(), so the final results remain unchanged.
    // ------------------------------------------------------------------

    // ey update:
    //
    // C code:
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Final result:
    //   ey[0][j] = _fict_[t]
    //   ey[i>0][j] as per stencil using old hz.
    //
    // In Halide layout, use ey_param(j, i) and hz_param(j, i).
    {
        // Safe neighbor read: for i = 0 we read hz(j, 0); for i > 0 we read hz(j, i-1).
        Expr hz_im1 = hz_param(j, max(i - 1, 0));
        Expr ey_update = ey_param(j, i) - half * (hz_param(j, i) - hz_im1);

        // Row 0 takes fict_param; other rows take the update.
        ey1(j, i) = select(i == 0, fict_param, ey_update);
    }

    // ex update:
    //
    // C code:
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Final result:
    //   ex[i][0] unchanged
    //   ex[i][j>0] updated.
    //
    // In Halide layout, use ex_param(j, i) and hz_param(j, i).
    {
        // Safe neighbor read: for j = 0 we read hz(0, i); for j > 0 we read hz(j-1, i).
        Expr hz_jm1 = hz_param(max(j - 1, 0), i);
        Expr ex_update = ex_param(j, i) - half * (hz_param(j, i) - hz_jm1);

        // Column 0 stays as original ex; others are updated.
        ex1(j, i) = select(j == 0, ex_param(j, i), ex_update);
    }

    // hz update:
    //
    // C code:
    //   for (i = 0; i < nx - 1; i++)
    //     for (j = 0; j < ny - 1; j++)
    //       hz[i][j] = hz[i][j]
    //                  - 0.7 * (ex[i][j+1] - ex[i][j]
    //                          + ey[i+1][j] - ey[i][j]);
    //
    // Final result:
    //   interior (i < nx-1, j < ny-1) updated using *new* ex,ey
    //   last row/col unchanged.
    //
    // In Halide layout, ex1(j, i), ey1(j, i), hz_param(j, i).
    {
        // Only interior points [0..nx-2, 0..ny-2] are updated.
        Expr interior = (i < nx_minus_one) && (j < ny_minus_one);

        // Safe neighbor reads; clamping only matters on the boundary,
        // where 'interior' is false and the updated value is not used.
        Expr ex_right = ex1(min(j + 1, ny_minus_one), i);
        Expr ey_down  = ey1(j, min(i + 1, nx_minus_one));

        Expr hz_update =
            hz_param(j, i) -
            seven_tenths *
                ((ex_right - ex1(j, i)) +
                 (ey_down  - ey1(j, i)));

        // Interior updated, edges keep their old values.
        hz1(j, i) = select(interior, hz_update, hz_param(j, i));
    }

    // ------------------------------------------------------------------
    // Scheduling
    //
    // All three fields are 2D pointwise stencils over the same domain.
    // We:
    //   - compute each at the root level,
    //   - parallelize over rows (i),
    //   - vectorize across columns (j) with a natural hardware width.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = natural_vector_size(type_of<num_t>(), target);

    Var i_outer("i_outer"), i_inner("i_inner");

    ey1
        .compute_root()
        .split(i, i_outer, i_inner, 64)
        .parallel(i_outer)
        .vectorize(j, vec_width);

    ex1
        .compute_root()
        .split(i, i_outer, i_inner, 64)
        .parallel(i_outer)
        .vectorize(j, vec_width);

    hz1
        .compute_root()
        .split(i, i_outer, i_inner, 64)
        .parallel(i_outer)
        .vectorize(j, vec_width);

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
