```c++
#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, NX, NY, TMAX, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // _fict_[i] = (DATA_TYPE) i;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / cast<int>(nx);
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<int>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // We keep the init schedule simple – one-time cost is negligible
    // compared to the main time-stepping loop.

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // Build the Halide pipeline that performs a single time-step.
    //
    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // New fields after a single time step.
    //
    // IMPORTANT: We express each field as a pure Func (no RDom/update).
    // This makes scheduling much easier and lets Halide reason better
    // about data locality and vectorization. There are no true reductions
    // here – every (i,j) is written exactly once – so pure definitions
    // are the idiomatic form.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // Runtime extents (in index space) for boundary handling.
    // Dimension 0 is j in [0, ny-1], dimension 1 is i in [0, nx-1].
    Expr ny_extent = ex_param.dim(0).extent();
    Expr nx_extent = ex_param.dim(1).extent();
    Expr ny_minus_1 = ny_extent - 1;
    Expr nx_minus_1 = nx_extent - 1;

    //
    // ey update (two original C loops fused into a single pure definition):
    //
    // C code:
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Mapping to Halide coordinates ey(j, i) == ey[i][j]:
    //   if i == 0:
    //       ey_new = fict[t]
    //   else:
    //       ey_new = ey_old - 0.5 * (hz(i,j) - hz(i-1,j))
    //
    {
        // Use clamp when accessing i-1 so that the expression is defined
        // everywhere; for i==0 it becomes hz(i,0), but we ignore that
        // branch by selecting fict_param instead. This avoids any
        // out-of-bounds access while still matching the C semantics.
        Expr i_minus_1 = clamp(i - 1, 0, nx_minus_1);
        Expr ey_old    = ey_param(j, i);
        Expr hz_here   = hz_param(j, i);
        Expr hz_im1    = hz_param(j, i_minus_1);

        Expr ey_updated = ey_old - half * (hz_here - hz_im1);

        ey1(j, i) = select(i == 0, fict_param, ey_updated);
    }

    //
    // ex update:
    //
    // C code:
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Mapping to Halide coordinates ex(j, i) == ex[i][j]:
    //   if j == 0:
    //       ex_new = ex_old
    //   else:
    //       ex_new = ex_old - 0.5 * (hz(i,j) - hz(i,j-1))
    //
    {
        Expr j_minus_1 = clamp(j - 1, 0, ny_minus_1);
        Expr ex_old    = ex_param(j, i);
        Expr hz_here   = hz_param(j, i);
        Expr hz_jm1    = hz_param(j_minus_1, i);

        Expr ex_updated = ex_old - half * (hz_here - hz_jm1);

        ex1(j, i) = select(j == 0, ex_old, ex_updated);
    }

    //
    // hz update:
    //
    // C code:
    //   for (i = 0; i < nx - 1; i++)
    //     for (j = 0; j < ny - 1; j++)
    //       hz[i][j] -= 0.7 * (ex[i][j+1] - ex[i][j]
    //                          + ey[i+1][j] - ey[i][j]);
    //
    // Mapping to Halide coordinates hz(j, i) == hz[i][j]:
    //   if 0 <= i < nx-1 and 0 <= j < ny-1:
    //       use updated ex1, ey1
    //   else:
    //       hz_new = hz_old (edges are unchanged)
    //
    {
        // Neighbor indices with safe clamping; for boundary points
        // we will not use these values because we select hz_old there.
        Expr j_plus_1 = clamp(j + 1, 0, ny_minus_1);
        Expr i_plus_1 = clamp(i + 1, 0, nx_minus_1);

        Expr ex_here   = ex1(j,        i);
        Expr ex_right  = ex1(j_plus_1, i);
        Expr ey_here   = ey1(j, i);
        Expr ey_down   = ey1(j, i_plus_1);

        Expr interior = (j < ny_minus_1) && (i < nx_minus_1);

        Expr hz_old    = hz_param(j, i);
        Expr hz_update =
            hz_old - seven_tenths *
                ((ex_right - ex_here) +
                 (ey_down  - ey_here));

        hz1(j, i) = select(interior, hz_update, hz_old);
    }

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
    Pipeline fdtd_step({ex1, ey1, hz1});

    //
    // CPU schedule for good locality and parallelism:
    //
    //  - We parallelize over strips of the slow i-dimension (rows).
    //  - We vectorize across the fast j-dimension (columns).
    //  - All three outputs are scheduled compute_root; there are no
    //    inter-output dependencies except that hz1 reads ex1/ey1,
    //    which Halide respects automatically.
    //
    Target target = get_jit_target_from_environment();
    Type num_type = type_of<num_t>();
    int vec_width = target.natural_vector_size(num_type);
    if (vec_width < 1) {
        vec_width = 1;  // Fallback: no vectorization if not supported.
    }

    // Strip height along i (rows). 64 is a reasonable cache-friendly
    // size for large 2D grids on modern CPUs.
    const int tile_i = 64;

    Var io("io"), ii("ii");

    // ex1 schedule
    ex1.compute_root()
       .split(i, io, ii, tile_i)   // i = io*tile_i + ii
       .parallel(io);              // parallelize over row-strips
    if (vec_width > 1) {
        ex1.vectorize(j, vec_width);  // SIMD over columns
    }

    // ey1 schedule
    ey1.compute_root()
       .split(i, io, ii, tile_i)
       .parallel(io);
    if (vec_width > 1) {
        ey1.vectorize(j, vec_width);
    }

    // hz1 schedule: same pattern; this is the last stage that depends
    // on ex1 and ey1, but all three are compute_root so the dependency
    // order is enforced automatically by Halide.
    hz1.compute_root()
       .split(i, io, ii, tile_i)
       .parallel(io);
    if (vec_width > 1) {
        hz1.vectorize(j, vec_width);
    }

    // JIT-compile once; we'll re-use it for every time-step.
    fdtd_step.compile_jit(target);

    // Double-buffering pointers for time-stepping.
    Halide::Buffer<num_t, 2> *ex_curr = &exA;
    Halide::Buffer<num_t, 2> *ey_curr = &eyA;
    Halide::Buffer<num_t, 2> *hz_curr = &hzA;

    Halide::Buffer<num_t, 2> *ex_next = &exB;
    Halide::Buffer<num_t, 2> *ey_next = &eyB;
    Halide::Buffer<num_t, 2> *hz_next = &hzB;

    // Start timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Time-stepping loop (host-driven).
    for (int t = 0; t < tmax; t++) {
        // Bind current input fields.
        ex_param.set(*ex_curr);
        ey_param.set(*ey_curr);
        hz_param.set(*hz_curr);

        // Set current _fict_[t] value.
        fict_param.set(fict(t));

        // Realize next time-step into ex_next, ey_next, hz_next.
        Realization r({*ex_next, *ey_next, *hz_next});
        fdtd_step.realize(r);

        // Swap current and next buffers for the next iteration.
        std::swap(ex_curr, ex_next);
        std::swap(ey_curr, ey_next);
        std::swap(hz_curr, hz_next);
    }

    // Stop timing.
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Final fields are in *ex_curr, *ey_curr, *hz_curr.
    Halide::Buffer<num_t, 2> &ex_final = *ex_curr;
    Halide::Buffer<num_t, 2> &ey_final = *ey_curr;
    Halide::Buffer<num_t, 2> &hz_final = *hz_curr;

    // Optional: print the arrays to prevent dead-code elimination
    // (and to roughly match the original PolyBench behavior).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print ex
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ex_final(j, i) << '\n';
            }
        }

        // Print ey
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << ey_final(j, i) << '\n';
            }
        }

        // Print hz
        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                std::cerr << hz_final(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds (as in gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
