using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input arrays, translated from the original C init_array().
 *
 * C prototype:
 *   void init_array (int tmax, int nx, int ny,
 *                    DATA_TYPE ex[nx][ny],
 *                    DATA_TYPE ey[nx][ny],
 *                    DATA_TYPE hz[nx][ny],
 *                    DATA_TYPE _fict_[tmax])
 *
 * In Halide, we represent:
 *   ex,ey,hz as Buffer<num_t, 2> with shape (ny, nx) and access ex(j, i)
 *   _fict_   as Buffer<num_t, 1> with shape (tmax)
 */
static void init_array(int tmax,
                       int nx,
                       int ny,
                       Halide::Buffer<num_t, 2> ex,
                       Halide::Buffer<num_t, 2> ey,
                       Halide::Buffer<num_t, 2> hz,
                       Halide::Buffer<num_t, 1> fict) {
    Var i("i"), j("j"), t("t");

    Func init_ex("init_ex"), init_ey("init_ey"), init_hz("init_hz"), init_fict("init_fict");

    // _fict_[t] = (DATA_TYPE) t;
    init_fict(t) = cast<num_t>(t);

    // ex[i][j] = (i * (j+1)) / nx;
    // ey[i][j] = (i * (j+2)) / ny;
    // hz[i][j] = (i * (j+3)) / nx;
    //
    // Remember: Buffer is indexed as (j, i) == C's [i][j].
    init_ex(j, i) = cast<num_t>(i * (j + 1)) / cast<int>(nx);
    init_ey(j, i) = cast<num_t>(i * (j + 2)) / cast<int>(ny);
    init_hz(j, i) = cast<num_t>(i * (j + 3)) / cast<int>(nx);

    // ------------------------------------------------------------------
    // Schedule for initialization
    //
    // These arrays are large (NX, NY from PolyBench), so we vectorize
    // across the fast dimension (j == column) and parallelize across rows.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    init_fict
        .compute_root()
        .vectorize(t, vec_width)
        .parallel(t);

    init_ex
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_ey
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_hz
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided Buffers.
    init_fict.realize(fict);
    init_ex.realize(ex);
    init_ey.realize(ey);
    init_hz.realize(hz);
}

int main(int argc, char *argv[]) {
    // Problem sizes from PolyBench
    int tmax = TMAX;
    int nx   = NX;
    int ny   = NY;

    // Buffers for ex, ey, hz.
    //
    // C layout: ex[nx][ny] with ex[i][j]
    // Halide layout: (ny, nx) so that ex(j, i) corresponds to ex[i][j].
    Halide::Buffer<num_t, 2> exA(ny, nx);
    Halide::Buffer<num_t, 2> eyA(ny, nx);
    Halide::Buffer<num_t, 2> hzA(ny, nx);

    // Second set of buffers for double-buffering in time.
    Halide::Buffer<num_t, 2> exB(ny, nx);
    Halide::Buffer<num_t, 2> eyB(ny, nx);
    Halide::Buffer<num_t, 2> hzB(ny, nx);

    // _fict_[t] array
    Halide::Buffer<num_t, 1> fict(tmax);

    // Initialize arrays
    init_array(tmax, nx, ny, exA, eyA, hzA, fict);

    // ------------------------------------------------------------------
    // Build the Halide pipeline that performs a single time-step.
    // ------------------------------------------------------------------

    // Inputs for the pipeline (current time-step fields)
    ImageParam ex_param(type_of<num_t>(), 2, "ex_param");
    ImageParam ey_param(type_of<num_t>(), 2, "ey_param");
    ImageParam hz_param(type_of<num_t>(), 2, "hz_param");

    // Scalar parameter for _fict_[t] at the current time-step.
    Param<num_t> fict_param("fict_param");

    // Vars: j is the fast (x/column), i is the slow (y/row).
    Var j("j"), i("i");

    // Constants SCALAR_VAL(0.5) and SCALAR_VAL(0.7), in the correct numeric type.
    Expr half         = cast<num_t>(Expr(0.5));
    Expr seven_tenths = cast<num_t>(Expr(0.7));

    // New fields after a single time step.
    Func ey1("ey1"), ex1("ex1"), hz1("hz1");

    // ------------------------------------------------------------------
    // Pure definitions that exactly match the C loops.
    //
    // We avoid RDom-based updates here and instead write each update
    // as a single pure expression, guarded by select() for the
    // boundary conditions. This is both easier for Halide to
    // optimize and clearly expresses that each time-step is a
    // pointwise transformation depending only on the previous
    // time-step.
    //
    // Index mapping:
    //   C:  field[i][j]   with i in [0..nx-1], j in [0..ny-1]
    //   HL: field(j, i)   where dimension 0 == j, dimension 1 == i
    // ------------------------------------------------------------------

    // ey update in C:
    //   for (j = 0; j < ny; j++)
    //     ey[0][j] = _fict_[t];
    //   for (i = 1; i < nx; i++)
    //     for (j = 0; j < ny; j++)
    //       ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j]);
    //
    // Halide (i == row, j == column):
    //   row 0: set to fict_param
    //   rows 1..nx-1: stencil update using old hz.
    ey1(j, i) = select(
        i == 0,
        fict_param,
        ey_param(j, i) -
            half * (hz_param(j, i) - hz_param(j, i - 1)));

    // ex update in C:
    //   for (i = 0; i < nx; i++)
    //     for (j = 1; j < ny; j++)
    //       ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1]);
    //
    // Halide:
    //   column 0: unchanged
    //   columns 1..ny-1: stencil update using old hz.
    ex1(j, i) = select(
        j == 0,
        ex_param(j, i),
        ex_param(j, i) -
            half * (hz_param(j, i) - hz_param(j - 1, i)));

    // hz update in C:
    //   for (i = 0; i < nx - 1; i++)
    //     for (j = 0; j < ny - 1; j++)
    //       hz[i][j] = hz[i][j]
    //                  - 0.7 * (ex[i][j+1] - ex[i][j]
    //                          + ey[i+1][j] - ey[i][j]);
    //
    // Halide:
    //   interior (i < nx-1 && j < ny-1): update with new ex1,ey1
    //   last row/column: keep old hz.
    Expr nx_expr = Expr(nx);
    Expr ny_expr = Expr(ny);

    Expr interior = (i < nx_expr - 1) && (j < ny_expr - 1);

    hz1(j, i) = select(
        interior,
        hz_param(j, i) -
            seven_tenths *
                ((ex1(j + 1, i) - ex1(j, i)) +
                 (ey1(j, i + 1) - ey1(j, i))),
        hz_param(j, i));

    // ------------------------------------------------------------------
    // Scheduling: improve locality, vectorization, and parallelism.
    //
    // We compute each field at root (full 2D domain), tile in 2D,
    // parallelize across tiles, and vectorize across the contiguous
    // dimension j.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile sizes tuned for reasonably large PolyBench sizes; they
    // don't need to evenly divide NX/NY (Halide handles edge tiles).
    const int tile_j = 64;  // along columns (fast dimension)
    const int tile_i = 32;  // along rows   (slow dimension)

    Var jo("jo"), io("io"), ji("ji"), ii("ii"), tile("tile");

    // ex1 and ey1 are producers for hz1 and also outputs; we compute
    // them in tiled, parallel, vectorized fashion.
    ex1
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile)
        .parallel(tile)
        .vectorize(ji, vec_width);

    ey1
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile)
        .parallel(tile)
        .vectorize(ji, vec_width);

    // hz1 consumes ex1 and ey1; we use the same tiling strategy so
    // that access patterns match and stay cache-friendly.
    hz1
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile)
        .parallel(tile)
        .vectorize(ji, vec_width);

    // Build a Pipeline with three outputs: ex1, ey1, hz1.
